def delete_moc(delta, full):
    list_of_delete_moc = []
    for delta_moc in delta:
        if delta_moc['operation'] == 'create':
            delete_moc_dict = __make_moc_dict(name=delta_moc["distName"], operation="delete", parameters=[])
            list_of_delete_moc.append(delete_moc_dict)
            for full_moc in full:
                if delta_moc["distName"] == full_moc["distName"]:
                    raise AttributeError(
                        'Delta creates an object that already exists ({}).'.format(delta_moc["distName"])
                    )
    return list_of_delete_moc


def delete_parameters(delta, full):
    list_delete_param = []
    for delta_and_full_mocs in __find_the_same_mocs_in_delta_and_full(delta, full):
        list_of_full_param_name = [param['parameterName'] for param in delta_and_full_mocs["full_moc"]['parameters']]
        for delta_parameter in delta_and_full_mocs["delta_moc"]['parameters']:
            if (
                delta_parameter['parameterName'] not in list_of_full_param_name
                and delta_parameter['operation'] == 'update'
            ):
                param = __make_param_dict(
                    name=delta_parameter["parameterName"], operation="delete", value=delta_parameter["value"]
                )
                delete_param_dict = __make_moc_dict(
                    name=delta_and_full_mocs["delta_moc"]["distName"], operation=None, parameters=param
                )
                list_delete_param.append(delete_param_dict)
    return list_delete_param


def create_moc(delta, full):
    list_of_create_moc = []
    for delta_and_full_mocs in __find_the_same_mocs_in_delta_and_full(delta, full):
        if delta_and_full_mocs["delta_moc"]['operation'] == "delete":
            create_moc_dict = __make_moc_dict(
                name=delta_and_full_mocs["delta_moc"]["distName"],
                operation="create",
                parameters=delta_and_full_mocs["full_moc"]['parameters'],
            )
            list_of_create_moc.append(create_moc_dict)
    return list_of_create_moc


def create_parameters(delta, full):
    list_create_param = []
    for delta_and_full_mocs in __find_the_same_mocs_in_delta_and_full(delta, full):
        delta_moc = delta_and_full_mocs["delta_moc"]
        full_moc = delta_and_full_mocs['full_moc']
        for delta_and_full_param in __find_the_same_param_in_delta_moc_and_full_moc(delta_moc, full_moc):
            if delta_and_full_param["delta_params"]['operation'] == 'delete':
                param = __make_param_dict(
                    name=delta_and_full_param["delta_params"]["parameterName"],
                    operation="update",
                    value=delta_and_full_param["full_params"]['value'],
                )
                create_param_dict = __make_moc_dict(
                    name=delta_and_full_mocs["delta_moc"]["distName"], operation=None, parameters=param
                )
                list_create_param.append(create_param_dict)
    return list_create_param


def update_parameters(delta, full):
    list_update_param = []
    for delta_and_full_mocs in __find_the_same_mocs_in_delta_and_full(delta, full):
        delta_moc = delta_and_full_mocs["delta_moc"]
        full_moc = delta_and_full_mocs['full_moc']
        for delta_and_full_param in __find_the_same_param_in_delta_moc_and_full_moc(delta_moc, full_moc):
            if (
                delta_and_full_param["delta_params"]['value'] is not None
                and delta_and_full_param["delta_params"]['operation'] == 'update'
            ):
                param = __make_param_dict(
                    name=delta_and_full_param["delta_params"]["parameterName"],
                    operation=delta_and_full_param["delta_params"]['operation'],
                    value=delta_and_full_param["full_params"]['value'],
                )
                update_param_dict = __make_moc_dict(
                    name=delta_and_full_mocs["delta_moc"]["distName"], operation=None, parameters=param
                )
                list_update_param.append(update_param_dict)
    return list_update_param


def update_moc(delta, full):
    list_of_update_moc = []
    for delta_and_full_mocs in __find_the_same_mocs_in_delta_and_full(delta, full):
        if delta_and_full_mocs["delta_moc"]['operation'] == "update":
            update_moc_dict = __make_moc_dict(
                name=delta_and_full_mocs["delta_moc"]["distName"],
                operation=delta_and_full_mocs["delta_moc"]['operation'],
                parameters=[],
            )
            list_of_update_moc.append(update_moc_dict)
    return list_of_update_moc


def __make_moc_dict(name, operation, parameters):
    return {"distName": name, "operation": operation, "parameters": parameters}


def __make_param_dict(name, operation, value):
    return {"parameterName": name, "operation": operation, "value": value}


def __find_the_same_mocs_in_delta_and_full(delta, full):
    for delta_moc in delta:
        for full_moc in full:
            list_of_full_moc_name = [moc['distName'] for moc in full]
            if delta_moc["distName"] == full_moc["distName"]:
                yield {"delta_moc": delta_moc, "full_moc": full_moc}
            elif delta_moc["distName"] not in list_of_full_moc_name and delta_moc['operation'] == "delete":
                raise AttributeError('Delta deletes a non-existent object ({}).'.format(delta_moc["distName"]))
            elif delta_moc["distName"] not in list_of_full_moc_name and delta_moc['operation'] == "update":
                raise AttributeError('Delta updates a non-existent object ({}).'.format(delta_moc["distName"]))


def __find_the_same_param_in_delta_moc_and_full_moc(delta_moc, full_moc):
    for delta_parameters in delta_moc['parameters']:
        for full_parameters in full_moc['parameters']:
            list_of_full_param_name = [param['parameterName'] for param in full_moc['parameters']]
            if delta_parameters['parameterName'] == full_parameters['parameterName']:
                yield {"delta_params": delta_parameters, "full_params": full_parameters}
            elif (
                delta_parameters['parameterName'] not in list_of_full_param_name
                and delta_parameters['operation'] == "delete"
            ):
                raise AttributeError(
                    'Delta deletes a non-existent parameter ({}).'.format(delta_parameters['parameterName'])
                )
